import{_ as i,a0 as l,w as o,s as r,ao as d,I as e,x as n,a1 as a,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"解讀 ip 命令展示的網絡連接信息 | LCTT x X-CMD","titleTemplate":false,"description":"解讀 ip 命令展示的網絡連接信息 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解讀 ip 命令展示的網絡連接信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解讀 ip 命令展示的網絡連接信息 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180309 How to check your network connections on Linux","title":"解讀 ip 命令展示的網絡連接信息","tag":"201803","desc":""},"relativePath":"201803/20180309 How to check your network connections on Linux.md","filePath":"[post].md"}'),c={name:"201803/20180309 How to check your network connections on Linux.md"};function f(u,s,k,h,g,b){const t=l("Link");return o(),r("div",null,[s[19]||(s[19]=d(`<h1 id="解讀-ip-命令展示的網絡連接信息" tabindex="-1">解讀 ip 命令展示的網絡連接信息 <a class="header-anchor" href="#解讀-ip-命令展示的網絡連接信息" aria-label="Permalink to “解讀 ip 命令展示的網絡連接信息”">​</a></h1><p><img src="https://images.idgesg.net/images/article/2018/03/network-connections-100751906-large.jpg" alt=""></p><p><code>ip</code> 命令可以告訴你很多網絡連接配置和狀態的信息，但是所有這些詞和數字意味着什麼？ 讓我們深入瞭解一下，看看所有顯示的值都試圖告訴你什麼。</p><p>當您使用 <code>ip a</code>（或 <code>ip addr</code>）命令獲取系統上所有網絡接口的信息時，您將看到如下所示的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip a</span></span>
<span class="line"><span>1: lo: &lt;LOOPBACK,UP,LOWER_UP&gt; mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000</span></span>
<span class="line"><span> link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00</span></span>
<span class="line"><span> inet 127.0.0.1/8 scope host lo</span></span>
<span class="line"><span> valid_lft forever preferred_lft forever</span></span>
<span class="line"><span> inet6 ::1/128 scope host</span></span>
<span class="line"><span> valid_lft forever preferred_lft forever</span></span>
<span class="line"><span>2: enp0s25: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc pfifo_fast state UP group default qlen 1000</span></span>
<span class="line"><span> link/ether 00:1e:4f:c8:43:fc brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span> inet 192.168.0.24/24 brd 192.168.0.255 scope global dynamic enp0s25</span></span>
<span class="line"><span> valid_lft 57295sec preferred_lft 57295sec</span></span>
<span class="line"><span> inet6 fe80::2c8e:1de0:a862:14fd/64 scope link</span></span>
<span class="line"><span> valid_lft forever preferred_lft forever</span></span></code></pre></div><p>這個系統上的兩個接口 - 環回（<code>lo</code>）和網絡（<code>enp0s25</code>）——顯示了很多統計數據。 <code>lo</code> 接口顯然是<ruby>環回地址<rt>loolback</rt></ruby>。 我們可以在列表中看到環回 IPv4 地址（<code>127.0.0.1</code>）和環回 IPv6（<code>::1</code>）。 而普通的網絡接口更有趣。</p><h3 id="為什麼是-enp0s25-而不是-eth0" tabindex="-1">為什麼是 enp0s25 而不是 eth0 <a class="header-anchor" href="#為什麼是-enp0s25-而不是-eth0" aria-label="Permalink to “為什麼是 enp0s25 而不是 eth0”">​</a></h3><p>如果你想知道為什麼它在這個系統上被稱為 <code>enp0s25</code>，而不是可能更熟悉的 <code>eth0</code>，那我們可以稍微解釋一下。</p><p>新的命名方案被稱為“<ruby>可預測的網絡接口<rt>Predictable Network Interface</rt></ruby>”。 它已經在基於systemd 的 Linux 系統上使用了一段時間了。 接口名稱取決於硬件的物理位置。 <code>en</code> 僅僅就是 “ethernet” 的意思，就像 “eth” 用於對應 <code>eth0</code>，一樣。 <code>p</code> 是以太網卡的總線編號，<code>s</code> 是插槽編號。 所以 <code>enp0s25</code> 告訴我們很多我們正在使用的硬件的信息。</p><p><code>&lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt;</code> 這個配置串告訴我們：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BROADCAST 	該接口支持廣播</span></span>
<span class="line"><span>MULTICAST 	該接口支持多播</span></span>
<span class="line"><span>UP 			網絡接口已啓用</span></span>
<span class="line"><span>LOWER_UP 	網絡電纜已插入，設備已連接至網絡</span></span></code></pre></div><p>列出的其他值也告訴了我們很多關於接口的知識，但我們需要知道 <code>brd</code> 和 <code>qlen</code> 這些詞代表什麼意思。 所以，這裏顯示的是上面展示的 <code>ip</code> 信息的其餘部分的翻譯。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mtu 1500 									最大傳輸單位（數據包大小）為1,500字節</span></span>
<span class="line"><span>qdisc pfifo_fast 							用於數據包排隊</span></span>
<span class="line"><span>state UP 									網絡接口已啓用</span></span>
<span class="line"><span>group default 								接口組</span></span>
<span class="line"><span>qlen 1000 									傳輸隊列長度</span></span>
<span class="line"><span>link/ether 00:1e:4f:c8:43:fc 				接口的 MAC（硬件）地址</span></span>
<span class="line"><span>brd ff:ff:ff:ff:ff:ff 						廣播地址</span></span>
<span class="line"><span>inet 192.168.0.24/24 						IPv4 地址</span></span>
<span class="line"><span>brd 192.168.0.255 							廣播地址</span></span>
<span class="line"><span>scope global 								全局有效</span></span>
<span class="line"><span>dynamic enp0s25 							地址是動態分配的</span></span>
<span class="line"><span>valid_lft 80866sec 							IPv4 地址的有效使用期限</span></span>
<span class="line"><span>preferred_lft 80866sec 						IPv4 地址的首選生存期</span></span>
<span class="line"><span>inet6 fe80::2c8e:1de0:a862:14fd/64			IPv6 地址</span></span>
<span class="line"><span>scope link 									僅在此設備上有效</span></span>
<span class="line"><span>valid_lft forever 							IPv6 地址的有效使用期限</span></span>
<span class="line"><span>preferred_lft forever 						IPv6 地址的首選生存期</span></span></code></pre></div><p>您可能已經注意到，<code>ifconfig</code> 命令提供的一些信息未包含在 <code>ip a</code> 命令的輸出中 —— 例如傳輸數據包的統計信息。 如果您想查看發送和接收的數據包數量以及衝突數量的列表，可以使用以下 <code>ip</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip -s link show enp0s25</span></span>
<span class="line"><span>2: enp0s25: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc pfifo_fast state UP mode DEFAULT group default qlen 1000</span></span>
<span class="line"><span> link/ether 00:1e:4f:c8:43:fc brd ff:ff:ff:ff:ff:ff</span></span>
<span class="line"><span> RX: bytes packets errors dropped overrun mcast</span></span>
<span class="line"><span> 224258568 418718 0 0 0 84376</span></span>
<span class="line"><span> TX: bytes packets errors dropped carrier collsns</span></span>
<span class="line"><span> 6131373 78152 0 0 0 0</span></span></code></pre></div><p>另一個 <code>ip</code> 命令提供有關係統路由表的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip route show</span></span>
<span class="line"><span>default via 192.168.0.1 dev enp0s25 proto static metric 100</span></span>
<span class="line"><span>169.254.0.0/16 dev enp0s25 scope link metric 1000</span></span>
<span class="line"><span>192.168.0.0/24 dev enp0s25 proto kernel scope link src 192.168.0.24 metric 100</span></span></code></pre></div>`,17)),e("p",null,[s[1]||(s[1]=e("code",null,"ip",-1)),s[2]||(s[2]=n(" 命令是非常通用的。 您可以從 ",-1)),s[3]||(s[3]=e("code",null,"ip",-1)),s[4]||(s[4]=n(" 命令及其來自",-1)),a(t,{href:"https://access.redhat.com/sites/default/files/attachments/rh_ip_command_cheatsheet_1214_jcs_print.pdf"},{default:p(()=>[...s[0]||(s[0]=[n("Red Hat",-1)])]),_:1}),s[5]||(s[5]=n("的選項獲得有用的備忘單。",-1))]),s[20]||(s[20]=e("hr",null,null,-1)),e("p",null,[s[7]||(s[7]=n("via: ",-1)),a(t,{href:"https://www.networkworld.com/article/3262045/linux/checking-your-network-connections-on-linux.html"},{default:p(()=>[...s[6]||(s[6]=[n("https://www.networkworld.com/article/3262045/linux/checking-your-network-connections-on-linux.html",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=n("作者：",-1)),a(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[8]||(s[8]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[12]||(s[12]=n(" 譯者：",-1)),a(t,{href:"https://github.com/Flowsnow"},{default:p(()=>[...s[9]||(s[9]=[n("Flowsnow",-1)])]),_:1}),s[13]||(s[13]=n(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=n("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[n("LCTT",-1)])]),_:1}),s[17]||(s[17]=n(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[n("Linux中國",-1)])]),_:1}),s[18]||(s[18]=n(" 榮譽推出",-1))])])}const T=i(c,[["render",f]]);export{w as __pageData,T as default};
